python
def prefixStencilsPositiveInkInvoice(readings, k):
    a=readings
    out=[]
    sums=[0]
    for x in a: sums.append(sums[-1]+x)
    for i in range(len(a)): out.append(sums[i+1]-sums[max(0,i-k+1)])
    return sum(x for x in out if x>0)


java
class Solution {
  public int prefixStencilsPositiveInkInvoice(int[] readings, int k) {
    int[] a=readings; List<Integer> out=new ArrayList<>();
    {int[]sums=new int[a.length+1];for(int i=0;i<a.length;i++)sums[i+1]=sums[i]+a[i];for(int i=0;i<a.length;i++)out.add(sums[i+1]-sums[Math.max(0,i-k+1)]);}
    int answer=0;for(int x:out)if(x>0)answer+=x;return answer;
  }
}
